window.WP_PAPERS["hi"] = {"sections":[{"id":"title","label":"शीर्षक","scene":"coin","items":[{"t":"title","lines":["बिटकॉइन","एक सहकर्मी-से-सहकर्मी","इलेक्ट्रॉनिक मुद्रा","तंत्र।"]},{"t":"byline","text":"Satoshi {Nakamoto|Nakamoto.} {satoshin@gmx.com|} {www.bitcoin.org|}"}]},{"id":"abstract","label":"सार","scene":"p2p","items":[{"t":"abs1","text":"{सार।|सार।} इलेक्ट्रॉनिक मुद्रा का सहकर्मी-से-सहकर्मी के लिए शुद्ध संस्करण, ऑनलाइन भुगतान को एक पार्टी से दूसरी को बिना किसी वित्तीय संस्थान के बिना भेजने की अनुमति देगा। डिजिटल हस्ताक्षर समाधान का एक हिस्सा हैं, लेकिन अगर दोहरे-खर्च को रोकने के लिए फिर भी किसी विश्वसनीय तीसरी पार्टी की जरूरत पड़े तो डिजिटल हस्ताक्षर का मुख्य लाभ खो जाता है।"},{"t":"abs2","text":"हम सहकर्मी-से-सहकर्मी नेटवर्क का उपयोग कर दोहरे खर्च की समस्या का समाधान प्रस्तावित करते हैं। यह नेटवर्क लेनदेन को समय-छाप करने के लिए, हैश आधारित कार्य-का-प्रमाण प्रक्रिया की एक निरंतर शृंखला में हैशिंग करता है, जिस से एक रिकॉर्ड बनता है, रिकॉर्ड को बिना कार्य-का-प्रमाण प्रक्रिया को फिर से दोहराये बिना बदला नहीं जा सकता। सबसे लंबी शृंखला न केवल देखी गयी घटनाओं के अनुक्रम के प्रमाण के रूप में कार्य करती है, बल्कि सबूत है कि ये सीपीयू ऊर्जा के सबसे बड़े कुंड में से आयी है। जब तक सीपीयू की अधिकांश ऊर्जा उन ग्रंथियों द्वारा नियंत्रित की जाती है जो नेटवर्क पर हमला करने में सहयोग नहीं कर रही, वे ग्रंथियां सबसे लंबी शृंखला उत्पन्न करेंगी और नेटवर्क के हमलावरों को पीछे छोड़ देंगी। नेटवर्क को स्वयं न्यूनतम संरचना की आवश्यकता होती है। संदेशों को एक सर्वोत्तम प्रयास के आधार पर प्रसारित किया जाता है, ग्रंथियां नेटवर्क अपनी मर्जी से छोड़ सकती हैं, और उनकी अनुपस्थिति में क्या हुआ इसका सबूत सबसे लंबी काम-का-प्रमाण आधारित शृंखला को स्वीकार कर फिर से शामिल हो सकती हैं।"}]},{"id":"s1","num":"1","label":"परिचय","scene":"trust","items":[{"t":"h","text":"{१.|एक।} परिचय"},{"t":"p","text":"इंटरनेट पर व्यापार लगभग पूर्ण रूप से उन वित्तीय संस्थानों जो कि इलेक्ट्रॉनिक भुगतान को संचालित करने के लिए भरोसेमंद तृतीय पार्टी हैं, उन पर आधारित है। हाँलांकि यह तंत्र अधिकांश लेनदेन के लिए पर्याप्त रूप से काम करता है, फिर भी यह विश्वास आधारित मॉडल की अंतर्निहित कमज़ोरियों से पीड़ित है। पूरी तरह से गैर-प्रतिवर्ती लेनदेन वास्तव में संभव नहीं है, क्यूँकि वित्तीय संस्थान विवादों में मध्यस्थता करने से नहीं बच सकते हैं। मध्यस्थता की लागत लेनदेन की लागत को बढ़ाती है, न्यूनतम व्यवहारिक लेनदेन आकार को सीमित करती है और छोटे आकस्मिक लेनदेन के लिए संभावनाओं को खत्म कर देती है, और गैर-प्रतिवर्ती सेवाओं के लिए गैर-प्रतिवर्ती भुगतान करने की क्षमता में कमी की कीमत व्यापक होती है। प्रतिवर्तन की संभावना की वजह से, भरोसे की जरूरत बढ़ती है। व्यापारियों को अपने ग्राहकों से होशियार रहना चाहिए, जरूरत से ज्यादा जानकारी के लिए उन्हें परेशान करना चाहिए। एक निश्चित प्रतिशत धोखाधड़ी को नहीं टाला जा सकता, यह मान्य है। इन लागत और भुगतान की अनिश्चितताओं को स्वयं भौतिक मुद्रा का उपयोग करके टाला जा सकता है, लेकिन संचार चैनल पर बिना भरोसेमंद पार्टी के भुगतान की कोई प्रक्रियाविधि नहीं है।"},{"t":"p","text":"जरूरत क्या है फिर, एक इलेक्ट्रॉनिक भुगतान तंत्र जो विश्वास की बजाय क्रिप्टोग्राफिक सबूत पर आधारित है, यह बिना किसी भरोसेमंद तीसरी पार्टी के बिना दो इच्छुक पार्टियों को सीधे लेन-देन में सक्षम करता है। लेन-देन का हिसाब जिसे प्रतिवर्तित करना असंभव है वह विक्रेताओं को धोखाधड़ी से बचाएंगे, और खरीददारों को बचाने के लिए सामान्य एस्क्रो प्रणाली को आसानी से लागू किया जा सकता है। इस पेपर में, सहकर्मी-से-सहकर्मी वितरित समय-छाप सर्वर द्वारा लेन-देन के कालानुक्रमिक क्रम का प्रमाण सहित हिसाब बना कर हम दोहरे-खर्च की समस्या के समाधान का प्रस्ताव करते हैं। जब तक ईमानदार ग्रंथियां हमलावर ग्रंथियों के सहयोगी समूह से ज्यादा सीपीयू ऊर्जा नियंत्रित करती हैं तब तक यह तंत्र सुरक्षित है।"}]},{"id":"s2","num":"2","label":"लेनदेन","scene":"txchain","items":[{"t":"h","text":"{२.|दो।} लेनदेन"},{"t":"p","text":"हम इलेक्ट्रॉनिक सिक्के को डिजिटल हस्ताक्षरों की शृंखला के रूप में परिभाषित करते हैं। प्रत्येक सिक्के का मालिक पिछले लेनदेन के हैश और अगले मालिक की सार्वजनिक कुंजी को डिजिटल हस्ताक्षर करके और सिक्के के अंत में जोड़ कर स्थानांतरण कर सकता है। प्राप्तकर्ता मालिकाना शृंखला को सत्यापित करने के लिए हस्ताक्षरों की जांच कर सकता है।"},{"t":"fig","scene":"txchain","h":250},{"t":"p","text":"निश्चित रूप से यह समस्या है कि भुगतान पाने वाला नहीं जांच पाएगा कि मालिकों में से एक ने सिक्के का दोहरा खर्च नहीं किया है। एक साधारण समाधान यह है कि एक विश्वसनीय केंद्रीय प्राधिकरण या टकसाल को लाना जो हर लेनदेन के दोहरे खर्च की जांच करे। प्रत्येक लेन-देन के बाद, टकसाल द्वारा नया सिक्का जारी करने हेतु पुराना सिक्का टकसाल में जमा होना चाहिए तथा टकसाल से जारी किये सिक्कों पर ही दोहरे-खर्च ना करने का भरोसा किया जायेगा। इस समाधान के साथ यह समस्या है कि संपूर्ण धन प्रणाली तंत्र का भाग्य टकसाल चलाने वाली कंपनी पर निर्भर करता है, हर लेन-देन का माध्यम वही है, एक बैंक की तरह।"},{"t":"p","text":"हमें भुगतान पाने वालों को यह जानने के लिए कि पिछले मालिक ने किसी भी पुराने लेन-देन पर हस्ताक्षर नहीं किये हैं, एक रास्ता चाहिए। हमारे उद्देश्यों के लिए, सबसे पहला लेनदेन ही मायने रखता है, इसलिए हम बाद में दोहरे-खर्च लेनदेन के प्रयासों के बारे में परवाह नहीं करते। एक लेनदेन की अनुपस्थिति की पुष्टि करने का एकमात्र तरीका सभी लेनदेन के बारे में जागरूक होना है। टकसाल आधारित मॉडल में, टकसाल को सभी लेनदेन की जानकारी थी, पहला लेनदेन उसी आधार पर तय कर लिया गया। किसी विश्वसनीय पार्टी के बिना इसे पूरा करने के लिए सभी लेनदेन सार्वजनिक रूप से घोषित किया जाना चाहिए {[१]|} और हमें प्रतिभागियों के उस आदेश के एकल इतिहास, जिसमें उन्हें प्राप्त किया गया था की सहमति के लिए एक तंत्र चाहिए। भुगतान पाने वालों को इस बात का प्रमाण चाहिए कि प्रत्येक लेनदेन के समय, अधिकांश ग्रंथियाँ सहमत थीं कि यह पहले प्राप्त हुआ।"}]},{"id":"s3","num":"3","label":"समय-छाप सर्वर","scene":"timestamp","items":[{"t":"h","text":"{३.|तीन।} समय-छाप सर्वर"},{"t":"p","text":"हमारे द्वारा प्रस्तावित समाधान एक समय-छाप सर्वर से शुरू होता है। एक समय-छाप सर्वर, वस्तुओं के ब्लॉक का हैश जिसे समय-छाप करना है उन्हें लेकर करता है तथा उन्हें अखबार या यूज़नेट डाक की तरह व्यापक रूप से प्रकाशित करता है {[२-५]|}। समय-छाप प्रमाणित करता है कि डाटा का उस समय अस्तित्व था, ज़ाहिर है हैश में आने के लिए। प्रत्येक समय-छाप हैश में पुराना समय-छाप एक शृंखला बनाते हुए सम्मिलित करता है, एवं अतिरिक्त समय-छाप पहले वालों को और मज़बूत बनाते हैं।"},{"t":"fig","scene":"timestamp","h":170}]},{"id":"s4","num":"4","label":"कार्य-का-प्रमाण","scene":"pow","items":[{"t":"h","text":"{४.|चार।} कार्य-का-प्रमाण"},{"t":"p","text":"सहकर्मी-से-सहकर्मी के आधार पर वितरित समय-छाप सर्वर को लागू करने के लिए, हमें अखबार या यूज़नेट पोस्ट के बजाय एडम बैक की हैशकैश {[६]|} समान कार्य-का-प्रमाण तंत्र उपयोग करना होगा। कार्य-का-प्रमाण एक हैश होती हुई निश्चित का अवलोकन करना है, जैसे कि {SHA-२५६,|एस एच ए दो सौ छप्पन,} हैश कई शून्य बिट के साथ शुरू होता है। औसतन कार्य शून्य बिट्स की संख्या में घातीय है और एकल हैश निष्पादित करके सत्यापित किया जा सकता है।"},{"t":"p","text":"हमारे समय-छाप नेटवर्क के लिए, हम कार्य-का-प्रमाण प्रक्रिया जब तक कि एक निश्चित, जो ब्लॉक के हैश को ज़रूरी शून्य बिट्स ना दे, तब तक ब्लॉक में अस्थायी वृद्धि करके लागू करते हैं। एक बार सीपीयू का प्रयास कार्य-का-प्रमाण को संतुष्ट करने के लिए खर्च कर दिया तो ब्लॉक को बिना कार्य किये नहीं बदला जा सकता। जैसा कि सभी ब्लॉक एक के बाद एक शृंखला बना लेते हैं, तो एक ब्लॉक को बदलने के लिए उसके बाद के सभी ब्लॉकों को बदलना होगा।"},{"t":"fig","scene":"pow","h":170},{"t":"p","text":"कार्य-का-प्रमाण बहुमत आधारित निर्णय लेने में प्रतिनिधित्व का निर्धारण करने की समस्या को हल करता है। यदि बहुमत एक-आईपी-एड्रेस-एक-वोट पर आधारित होता, तो किसी के भी द्वारा बहुमत को कई आईपी आवंटित करके पलटा जा सकता था। कार्य-का-प्रमाण अनिवार्यतः ही एक-सीपीयू-एक-वोट है। बहुमत के निर्णय को सबसे लंबी शृंखला द्वारा दर्शाया जाता है, जिसमें अधिकतम कार्य-का-प्रमाण प्रयास लगा होता है। यदि अधिकांश सीपीयू ऊर्जा ईमानदार ग्रंथियों द्वारा नियंत्रित हैं तो ईमानदार शृंखला सबसे तेज़ी से आगे बढ़ेगी और किसी भी प्रतिस्पर्धा शृंखला को पीछे छोड़ देगी। पिछले ब्लॉक को बदलने के लिए, हमलावर को ब्लॉक के कार्य-का-प्रमाण फिर से दोहराना होगा, उस ब्लॉक के बाद के सभी ब्लॉक का भी और फिर भी ईमानदार ग्रंथियों के काम को पार करना होगा। यह हम बाद में दिखाएंगे कि सुस्त हमलावर को पकड़ने की संभावना आगामी ब्लॉक में जुड़ने की वजह से कैसे तेज़ी से कम हो जाती है।"},{"t":"p","text":"बढ़ी हुई हार्डवेयर की गति और चलती हुई ग्रंथियों की भिन्न-भिन्न इच्छाओं के लिए, कार्य-का-प्रमाण की कठिनाई औसतन गति जो प्रति घंटे ब्लॉक की संख्या से निकलती है। अगर ब्लॉक बहुत तेज़ी से उत्पन्न होते हैं, तो कठिनाई बढ़ जाती है।"}]},{"id":"s5","num":"5","label":"नेटवर्क","scene":"network","items":[{"t":"h","text":"{५.|पाँच।} नेटवर्क"},{"t":"p","text":"नेटवर्क चलाने के चरण इस प्रकार हैं:"},{"t":"li","text":"{a.|ए.} नए लेनदेन सभी ग्रंथियों में प्रसारित किए जाते हैं।"},{"t":"li","text":"{b.|बी.} प्रत्येक ग्रंथि एक ब्लॉक में नए लेनदेन एकत्र करती है।"},{"t":"li","text":"{c.|सी.} प्रत्येक ग्रंथि अपने ब्लॉक के लिए एक कठिन कार्य-का-प्रमाण खोजने पर काम करती है।"},{"t":"li","text":"{d.|डी.} जब कोई ग्रंथि कार्य-का-प्रमाण देखता है, तो यह ब्लॉक को सभी ग्रंथियों में प्रसारित करता है।"},{"t":"li","text":"{e.|ई.} ग्रंथिया ब्लॉक को केवल तभी स्वीकार करती है यदि इसमें सभी लेनदेन वैध हैं और पहले से ही खर्च नहीं किए गए हैं।"},{"t":"li","text":"{f.|एफ.} ग्रंथियां ब्लॉक स्वीकृति की अभिव्यक्ति शृंखला में अगले ब्लॉक के निर्माण को स्वीकृत ब्लॉक की हैश को पूर्व हैश मानकर करती है।"},{"t":"p","text":"ग्रंथिया हमेशा सबसे लंबी शृंखला को ही ठीक मानती हैं और उसे विस्तारित करने के लिए काम करती रहेगी। यदि दो ग्रंथियां अगले ब्लॉक के अलग-अलग संस्करणों को एक साथ प्रसारित करती हैं, तो कुछ ग्रंथियां पहला या दूसरा ब्लॉक पहले प्राप्त करेंगी। उस स्थिति में, वे जो पहले प्राप्त हुआ उसपर काम करेंगे लेकिन दूसरी शाखा को बचा कर रखेंगे अगर वह सबसे लंबी हो जाए तो। गुंठी तब सुलझेगी जब नया कार्य-का-प्रमाण मिलेगा और एक शाखा और लंबी हो जाएगी, जो ग्रंथियां दूसरी शाखाओं पर काम कर रहे हैं वो भी उन्हें छोड़कर लंबी शाखा पर आ जाएंगी।"},{"t":"p","text":"नए लेनदेन के प्रसारण के लिए सभी ग्रंथियों तक पहुंचने की आवश्यकता नहीं है। जब तक वे अनेक ग्रंथियों तक पहुँचते हैं, उस से पहले ही वो एक ब्लॉक में पहुँच जाएंगे। ब्लॉक प्रसारण भी गिराए गए संदेशों के प्रति सहनशील हैं। यदि एक ग्रंथि को एक ब्लॉक प्राप्त नहीं होता है, तो वह उसका अनुरोध तब करेगी जब उससे अगला ब्लॉक मिलने पर उसे एक ब्लॉक की कमी अनुभव होगी।"}]},{"id":"s6","num":"6","label":"प्रोत्साहन","scene":"incentive","items":[{"t":"h","text":"{६.|छह।} प्रोत्साहन"},{"t":"p","text":"परंपरानुसार ब्लॉक का पहला लेनदेन एक विशेष लेनदेन है जो ब्लॉक के निर्माता के स्वामित्व वाला एक नया सिक्का शुरू करता है। यह ग्रंथियों को नेटवर्क से जुड़ने के लिए प्रोत्साहित करता है, और शुरू में सिक्कों को प्रचलन में लाने का एक तरीका प्रदान करता है, क्योंकि उन्हें जारी करने के लिए कोई केंद्रीय प्राधिकरण नहीं है। नए सिक्कों की नियमित वृद्धि सोने के खनिकों के अनुरूप है जो मुद्रा-चलन में और सोना जोड़ने के लिए अपने संसाधन व्यय करते हैं। हमारे मामले में, यह सीपीयू समय और ऊर्जा है जो व्यय किया जाता है।"},{"t":"p","text":"प्रोत्साहन को लेनदेन शुल्क के साथ भी वित्तपोषित किया जा सकता है। यदि किसी लेन-देन का आउटपुट मूल्य उसके इनपुट मूल्य से कम है, तो उनके बीच का अंतर एक लेनदेन शुल्क है जो लेनदेन वाले ब्लॉक के प्रोत्साहन मूल्य में जोड़ा जाता है। एक बार जब पूर्व निर्धारित सिक्के प्रचलन में आ जाएँगे तब प्रोत्साहन राशि लेनदेन शुल्क रहेगा जो की मुद्रास्फीति मुक्त रहेगी।"},{"t":"p","text":"प्रोत्साहन शुल्क ग्रंथियों को ईमानदार रहने के लिए बढ़ावा देगा। अगर एक लालची हमलावर सभी ईमानदार नोड्स की तुलना में अधिक सीपीयू शक्ति को इकट्ठा करने में सक्षम हो जाता है, तो उसे किए गए भुगतान वापस चुरा कर लोगों को ठगने या फिर उस शक्ति का नए सिक्के उत्पाद करने में से एक निर्णय लेना होगा। उसे नियमों द्वारा खेलना अधिक लाभदायक लगेगा, तंत्र को कमज़ोर और अपने स्वयं के धन की वैधता को कम करने की तुलना में ऐसे नियम जो बाकी सभी से नए सिक्के अर्जित करने में उसका पक्ष लेंगे।"}]},{"id":"s7","num":"7","label":"डिस्क स्पेस का सुधार","scene":"merkle","items":[{"t":"h","text":"{७.|सात।} डिस्क स्पेस का सुधार"},{"t":"p","text":"एक बार जब सिक्के का नवीनतम लेनदेन पर्याप्त ब्लॉकों के नीचे दब जाता है, तो इससे पहले के खर्च किए गए सभी लेनदेन को निकाला जा सकता है। इसे बिना ब्लॉक का हैश तोड़े बिना करने के लिए, लेन-देन को एक मरकल ट्री में हैश किया जाता है {[७][२][५],|,} केवल रूट को ब्लॉक की हैश में सम्मिलित कर। आंतरिक हैश को संग्रहित करने की आवश्यकता नहीं है।"},{"t":"fig","scene":"merkle","h":300},{"t":"p","text":"बिना लेन-देन वाला ब्लॉक हेडर लगभग 80 बाइट्स का होगा। अगर हम मान लें कि ब्लॉक हर 10 मिनट में उत्पन्न होते हैं, {80 बाइट्स * 6 * 24 * 365 = ४.२ MB|80 बाइट्स, गुणा 6, गुणा 24, गुणा 365, बराबर ४.२ मेगाबाइट} प्रति वर्ष। २००८ तक आमतौर पर कंप्यूटर सिस्टम की {2GB|2 गीगाबाइट} RAM के साथ बिक्री होती है, और मूर की विधि प्रति वर्ष {1.2GB|1.2 गीगाबाइट} की वर्तमान वृद्धि की भविष्यवाणी करती है, और ब्लॉक हेडर को स्मृति में रखने पर भी स्टोरेज एक समस्या नहीं होनी चाहिए।"}]},{"id":"s8","num":"8","label":"सरलीकृत भुगतान सत्यापन","scene":"spv","items":[{"t":"h","text":"{८.|आठ।} सरलीकृत भुगतान सत्यापन"},{"t":"p","text":"पूर्ण नेटवर्क ग्रंथि चलाए बिना भुगतानों को सत्यापित करना संभव है। एक उपयोगकर्ता को सबसे लंबी कार्य-का-प्रमाण शृंखला के ब्लॉक हेडर की एक प्रति रखने की आवश्यकता होती है, जिसे वह नेटवर्क ग्रंथियों की जांच कर प्राप्त कर सकता है, लेकिन यह जांच जब तक चलेगी जब तक वह आश्वस्त ना हो जाए कि उसके पास सबसे लंबी शृंखला है और लेनदेन को समय-छाप किये ब्लॉक से जोड़ने वाली मार्कल शाखा हासिल कर ले। वह खुद के लिए लेनदेन की जांच नहीं कर सकता, लेकिन इसे शृंखला में एक जगह जोड़कर वह देख सकता है कि नेटवर्क ग्रंथि ने इसे स्वीकार कर लिया है और उसके बाद आगे बढ़े हुए ब्लॉक भी पुष्टि करते हैं कि नेटवर्क ने इसे स्वीकार कर लिया है।"},{"t":"fig","scene":"spv","h":250},{"t":"p","text":"इस प्रकार, सत्यापन तब तक विश्वसनीय है जब तक कि ईमानदार ग्रंथिया नेटवर्क को नियंत्रित करती हैं, लेकिन नेटवर्क को अगर हमलावरों ने काबू कर लिया तो वो ज्यादा संवेदनशील होगा। जबकि नेटवर्क ग्रंथिया अपने लिए लेनदेन खुद सत्यापित कर सकती हैं, वहीं सरल विधि को किसी हमलावर के मनगढ़ंत लेनदेन से मूर्ख बनाया जा सकता है जब तक कि हमलावर नेटवर्क को अपने काबू में रख सकता है। इसके बचाव की एक रणनीति, नेटवर्क ग्रंथियों जब एक अमान्य ब्लॉक का पता लगाएं तो उनसे चेतावनी स्वीकार करनी होगी, यह चेतावनी यूजर के सॉफ्टवेयर को बेजोड़ता की पुष्टि करने हेतु पूरा ब्लॉक और सूचित लेनदेन को डाउनलोड करने के लिए अनुबोधित करेगी। लगातार भुगतान प्राप्त करने वाले व्यवसाय अब भी अधिक स्वतंत्र सुरक्षा और त्वरित सत्यापन के लिए अपनी ग्रंथि चलाना चाहेंगे।"}]},{"id":"s9","num":"9","label":"संयोजन और मूल्य विभाजन","scene":"inout","items":[{"t":"h","text":"{९.|नौ।} संयोजन और मूल्य विभाजन"},{"t":"p","text":"हालाँकि सिक्कों को व्यक्तिगत रूप से संभालना संभव होगा, लेकिन हस्तांतरण में हर सेंट के लिए एक अलग लेन-देन करना व्यापक होगा। मूल्य को विभाजित और संयुक्त करने की अनुमति देने के लिए, लेनदेन में कई इनपुट और आउटपुट होते हैं। आम तौर पर एक बड़े पिछले लेनदेन से या तो एक इनपुट होगा या छोटी मात्राओं के संयोजन वाले कई इनपुट, और अधिकांश दो आउटपुट रहेंगे: एक भुगतान के लिए, और यदि कोई छूटा भुगतान हो तो प्रेषक को वापस देने के लिए।"},{"t":"fig","scene":"inout","h":190},{"t":"p","text":"यह ध्यान दिया जाना चाहिए कि फैन-आउट, जहां एक लेनदेन कई लेनदेन पर निर्भर करता है, और उन लेनदेन पर कई और निर्भर करते हैं, इधर ऐसी कोई समस्या नहीं है। लेन-देन के इतिहास की पूरी स्टैंडअलोन कॉपी निकालने की आवश्यकता कभी नहीं होती है।"}]},{"id":"s10","num":"10","label":"गोपनीयता","scene":"privacy","items":[{"t":"h","text":"{१०.|दस।} गोपनीयता"},{"t":"p","text":"पारंपरिक बैंकिंग मॉडल शामिल पार्टियों और विश्वसनीय तीसरी पार्टी को सूचना की पहुंच से सीमित करके गोपनीयता के स्तर को हासिल करता है। सभी लेनदेन को सार्वजनिक करने की आवश्यकता इस तरीके को रोकती है, लेकिन गोपनीयता को अभी भी दूसरी जगह सूचना के प्रवाह को तोड़कर बनाए रखा जा सकता है: सार्वजनिक कुंजियों को गुमनाम रखकर। जनता यह देख सकती है कि कोई व्यक्ति किसी और को राशि भेज रहा है, लेकिन बिना लेनदेन की शृंखला की सूचना के। यह स्टॉक एक्सचेजों द्वारा जारी की गई सूचना के स्तर के समान है, जहां व्यक्तिगत ट्रेडों के समय और आकार की \"टेप\" को सार्वजनिक किया जाता है, लेकिन यह बताए बिना कि कौनसी पार्टी ने क्या लेनदेन किया।"},{"t":"fig","scene":"privacy","h":210},{"t":"p","text":"अतिरिक्त फायरवॉल के रूप में, प्रत्येक लेनदेन का एक सार्वजनिक मालिक से जुड़ाव रोकने के लिए हमेशा नयी कुंजी के जोड़ों का इस्तेमाल होना चाहिए। मल्टी-इनपुट लेनदेन के साथ कुछ लिंकिंग अभी भी अपरिहार्य है, जो आवश्यक रूप से प्रकट करते हैं कि उनके इनपुट एक ही मालिक के स्वामित्व में थे। विपत्ति यह है कि यदि एक कुंजी के मालिक का पता चलता है, तो लिंकिंग की प्रक्रिया अन्य लेनदेन जो एक ही मालिक के थे उन्हें भी उजागर कर सकता है।"}]},{"id":"s11","num":"11","label":"गणना","scene":"calc","items":[{"t":"h","text":"{११.|ग्यारह।} गणना"},{"t":"p","text":"हम एक हमलावर के परिदृश्य पर विचार करते हैं जो ईमानदार शृंखला की तुलना में तेजी से वैकल्पिक शृंखला उत्पन्न करने की कोशिश कर रहा है। यहां तक कि अगर यह पूरा भी किया जाता है, तो यह तंत्र को मनमाने ढंग से बदलाव के लिए नहीं खोलता है, जैसे कि पतली हवा में से मूल्य पैदा करना या ऐसा पैसा लेना जो कभी हमलावर का था ही नहीं। भुगतान के रूप में एक अमान्य लेनदेन को ग्रंथियां स्वीकार नहीं करेंगी, और ईमानदार ग्रंथिया उस ब्लॉक को कभी भी स्वीकार नहीं करेंगी। एक हमलावर केवल अपने स्वयं के लेन-देन में से एक को बदलने की कोशिश कर सकता है ताकि वह हाल ही में खर्च किए गए धन को वापस ले सके।"},{"t":"p","text":"ईमानदार शृंखला और हमलावर शृंखला के बीच की दौड़ को एक द्विपद रैंडम वॉक के रूप में चिह्नित किया जा सकता है। एक ब्लॉक द्वारा विस्तारित की जा रही ईमानदार शृंखला सफल परिणाम है, इसकी अग्रिता को {+१,|प्लस एक,} से बढ़ाता है, और विफल परिणाम हमलावर की शृंखला का एक ब्लॉक द्वारा विस्तार होना है, जिससे अंतराल {-१|माइनस एक} से कम हो जाता है।"},{"t":"p","text":"एक हमलावर को एक दिए गए घाटे से पकड़ने की संभावना एक गेंबलर रुइन प्रॉब्लम के अनुरूप है। मान लीजिए कि असीमित क्रेडिट से लदा एक जुआरी घाटे में शुरू होता है और ब्रेक-इवन तक पहुंचने की कोशिश में संभावित रूप से अनंत आज़माइश खेलता है। क्या वह कभी भी ब्रेक-इवन तक पहुंचता है, या कि एक हमलावर कभी भी ईमानदार शृंखला के पास पहुँच सकता है, हम उस संभावना की गणना कर सकते हैं जो कि इस प्रकार है {[८]:|:}"},{"t":"def","text":"{p =|p बराबर} एक ईमानदार ग्रंथि की अगले ब्लॉक को ढूंढने की संभावना"},{"t":"def","text":"{q =|q बराबर} हमलावर के अगले ब्लॉक ढूंढने की संभावना"},{"t":"def","text":"{q_z =|क्यू सब ज़ेड बराबर} z ब्लॉक पिछड़े हमलावर आगे वाले ब्लॉक के सामान आने की संभावना"},{"t":"math","id":"qz","say":"क्यू सब ज़ेड एक है, अगर p, q से कम या बराबर है। या q भाग p, z की घात पर, अगर p, q से बड़ा है।"},{"t":"p","text":"हम मान लेते हैं कि {p>q है,|p, q से बड़ा है,} हमलावर के हमला करने की संभावना तेज़ी से कम होती है क्यूंकि उसे अब ज्यादा ब्लॉक पार करने होंगे। उसके विरुद्ध चल रही बाधाओं के साथ, यदि वह जल्दी से एक झप्पा नहीं मारता, तो उसके अवसर ना बराबर हो जाते हैं क्यूंकि वह और पीछे हो जाता है।"},{"t":"p","text":"अब हम विचार करते हैं कि एक नए लेनदेन के प्राप्तकर्ता को कितनी देर तक प्रतीक्षा करने की आवश्यकता है जब तक कि प्रेषक लेनदेन को बदल नहीं सकता। हम मानते हैं कि प्रेषक एक हमलावर है जो प्राप्तकर्ता को यह विश्वास दिलाना चाहता है कि उसने उसे कुछ समय के लिए भुगतान किया है, और कुछ समय पश्चात भुगतान वापस अपने आप को पलट ले। ऐसा होने पर भुगतान पाने वाला सतर्क हो जाएगा, लेकिन भुगतान करने वाले को उम्मीद है कि तब तक बहुत देर हो जाएगी।"},{"t":"p","text":"प्राप्ता एक नई कुंजी की जोड़ी उत्पन्न करता है और हस्ताक्षर करने से कुछ समय पहले प्रेषक को सार्वजनिक कुंजी दे ता है। यह भुगतान करने वाले को, निरंतर उसपर काम करके जब तक कि वह भाग्यशाली नहीं होता समय से पहले आगे जाकर एक ब्लॉक की शृंखला बनाकर और उसी समय लेनदेन का निष्पादन करने से रोकता है। एक बार लेनदेन भेजे जाने के बाद, बेईमान प्रेषक अपने लेनदेन के वैकल्पिक संस्करण वाले समानांतर शृंखला पर गुप्त रूप से काम करना शुरू कर देता है।"},{"t":"p","text":"भुगतान पाने वाला तब तक प्रतीक्षा करता है जब तक कि लेन-देन को एक ब्लॉक में नहीं जोड़ा जाता है और उस ब्लॉक के बाद 'z' संख्या जितने ब्लॉक जोड़ दिए जाते हैं। उसे पता नहीं है कि हमलावर ने कितनी प्रगति की है, लेकिन यह मानकर कि ईमानदार ब्लॉक ने प्रति ब्लॉक औसतन अपेक्षित समय लिया है, हमलावर की संभावित प्रगति अपेक्षित मान के साथ पॉइसन वितरण होगी:"},{"t":"math","id":"lambda","say":"लैम्ब्डा बराबर z गुणा q भाग p।"},{"t":"p","text":"हमलावर अभी भी पकड़ सकता है या नहीं इसकी संभावना का अनुमान लगाने के लिए, पॉइसन घनत्व को हम प्रत्येक प्रगति के मान (पिछड़े बिंदु से आगे बढ़ने की प्रगति की संभावना का मान) से गुणा करते हैं:"},{"t":"math","id":"sum","say":"योग, k शून्य से अनंत तक, लैम्ब्डा की घात k, गुणा ई की घात ऋण लैम्ब्डा, भाग k क्रमगुणित, गुणा q भाग p की घात z घटा k, अगर k, z से कम या बराबर है। या एक, अगर k, z से बड़ा है।"},{"t":"p","text":"वितरण की अनंत अनुगामी समूह को जमा करने से बचने के लिए…"},{"t":"math","id":"rearr","say":"एक, घटा योग, k शून्य से z तक, लैम्ब्डा की घात k, ई की घात ऋण लैम्ब्डा, भाग k क्रमगुणित, गुणा एक घटा q भाग p की घात z घटा k।"},{"t":"p","text":"C कोड में बदलते हुए..."},{"t":"code","hold":5},{"t":"p","text":"कुछ परिणाम को चलाकर, हम देख सकते हैं कि संभावना z के साथ घातीय रूप से गिर जाती है।"},{"t":"results","hold":5.5},{"t":"p","text":"P के लिए हल {0.1%|0.1 प्रतिशत} से कम..."},{"t":"ztable","head":"{P < 0.001|P, 0.001 से कम है।}","rows":[["{q=0.10|q बराबर 0.10,}","{z=5|z बराबर 5.}"],["{q=0.15|q बराबर 0.15,}","{z=8|z बराबर 8.}"],["{q=0.20|q बराबर 0.20,}","{z=11|z बराबर 11.}"],["{q=0.25|q बराबर 0.25,}","{z=15|z बराबर 15.}"],["{q=0.30|q बराबर 0.30,}","{z=24|z बराबर 24.}"],["{q=0.35|q बराबर 0.35,}","{z=41|z बराबर 41.}"],["{q=0.40|q बराबर 0.40,}","{z=89|z बराबर 89.}"],["{q=0.45|q बराबर 0.45,}","{z=340|z बराबर 340.}"]]}]},{"id":"s12","num":"12","label":"निष्कर्ष","scene":"conclusion","items":[{"t":"h","text":"{१२.|बारह।} निष्कर्ष"},{"t":"p","text":"हमने भरोसे पर आधारित किए बिना इलेक्ट्रॉनिक लेनदेन के लिए एक तंत्र प्रस्तावित किया है। हमने डिजिटल हस्ताक्षरों से बने सिक्कों की सामान्य रूपरेखा के साथ शुरुआत की, जो स्वामित्व का मजबूत नियंत्रण प्रदान करता है, लेकिन दोहरे खर्च को रोकने के तरीके के बिना यह तंत्र अधूरा है। इसका हल करने के लिए, हमने कार्य-का-प्रमाण का उपयोग करके सार्वजनिक लेनदेन को रिकॉर्ड कर एक सहकर्मी-से-सहकर्मी नेटवर्क को प्रस्तावित किया, यह सार्वजनिक लेनदेन हमलावर द्वारा बदलाव के लिए जल्दी से कम्प्यूटेशनल रूप से अव्यावहारिक हो जाता है अगर ईमानदार ग्रंथियां सीपीयू शक्ति के बहुमत को नियंत्रित करती हैं। नेटवर्क अपनी असंरचित सादगी में मजबूत है। थोड़े से समन्वय के साथ सभी ग्रंथियां एक ही बार में काम करती हैं। उन्हें पहचानने की आवश्यकता नहीं है, क्योंकि संदेशों को किसी विशेष स्थान पर नहीं भेजा जाता, केवल सर्वोत्तम प्रयास के आधार पर वितरित करने की आवश्यकता होती है। ग्रंथियां नेटवर्क अपनी मर्जी से छोड़ सकती हैं, और उनकी अनुपस्थिति में क्या हुआ इसका सबूत सबसे लंबी काम-का-प्रमाण आधारित शृंखला को स्वीकार कर फिर से शामिल हो सकती हैं। वे अपनी सीपीयू ऊर्जा के साथ वोट करते हैं, वैध ब्लॉकों की स्वीकृति प्रदान करते हैं और उन्हें काम करने से इनकार करके अमान्य ब्लॉकों को अस्वीकार करते हैं। इस आम सहमति तंत्र के साथ किसी भी आवश्यक नियम और प्रोत्साहन को लागू किया जा सकता है।"}]},{"id":"refs","label":"संदर्भ","scene":null,"items":[{"t":"refs","list":["W. Dai, \"b-money,\" http://www.weidai.com/bmoney.txt, 1998.","H. Massias, X.S. Avila, and J.-J. Quisquater, \"Design of a secure timestamping service with minimal trust requirements,\" In 20th Symposium on Information Theory in the Benelux, May 1999.","S. Haber, W.S. Stornetta, \"How to time-stamp a digital document,\" In Journal of Cryptology, vol 3, no 2, pages 99-111, 1991.","D. Bayer, S. Haber, W.S. Stornetta, \"Improving the efficiency and reliability of digital time-stamping,\" In Sequences II: Methods in Communication, Security and Computer Science, pages 329-334, 1993.","S. Haber, W.S. Stornetta, \"Secure names for bit-strings,\" In Proceedings of the 4th ACM Conference on Computer and Communications Security, pages 28-35, April 1997.","A. Back, \"Hashcash - a denial of service counter-measure,\" http://www.hashcash.org/papers/hashcash.pdf, 2002.","R.C. Merkle, \"Protocols for public key cryptosystems,\" In Proc. 1980 Symposium on Security and Privacy, IEEE Computer Society, pages 122-133, April 1980.","W. Feller, \"An introduction to probability theory and its applications,\" 1957."]}]}]};
